parameters.functionCode:
// ─────────────────────────────────────────────────────────────
// Hashear dados do comprador em SHA-256 (padrão Meta CAPI)
// Compatível com payload Hotmart PURCHASE_COMPLETE
// ─────────────────────────────────────────────────────────────
const crypto = require('crypto');

function sha256(str) {
  if (!str || String(str).trim() === '') return null;
  return crypto.createHash('sha256')
    .update(String(str).trim().toLowerCase())
    .digest('hex');
}

function normalizePhone(phone) {
  if (!phone) return null;
  const digits = String(phone).replace(/\D/g, '');
  if (digits.length === 0) return null;
  // Se não tem código de país (10 dígitos), adiciona +52 (México)
  // Ajustar conforme mercado predominante
  if (digits.length === 10) return '52' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return digits; // US/CA
  return digits;
}

// Compatibilidade com estruturas do Hotmart (v1 e v2)
const payload = $input.first().json;
const data = payload.data || payload;
const purchase = data.purchase || {};
const buyer = data.buyer || {};
const subscription = data.subscription || {};

// Dados do comprador
const email     = buyer.email || '';
const fullName  = (buyer.name || '').trim();
const nameParts = fullName.split(/\s+/);
const firstName = nameParts[0] || '';
const lastName  = nameParts.slice(1).join(' ') || '';
const phone     = buyer.phone || buyer.cellphone || '';
const country   = (buyer.address?.country_iso || buyer.country_iso || 'mx').toLowerCase();
const zip       = (buyer.address?.zip_code || buyer.zip_code || '').replace(/\D/g, '');

// Valor da compra
const orderValue = (purchase.price?.value || purchase.value || 9.90);
const orderId    = purchase.transaction || purchase.order_id || ('rf_' + Date.now());

// Event ID: prioriza o sck enviado pelo browser via URL do checkout
// rfTrackIC() injeta ?sck=rf_ic_xxx na URL → Hotmart repassa no webhook
// Isso garante deduplicação: mesmo event_id no browser e na CAPI
const sckFromBrowser =
  (data.purchase && data.purchase.tracking && (data.purchase.tracking.source_sck || data.purchase.tracking.sck)) ||
  (purchase && (purchase.sck || purchase.source_sck)) ||
  null;
const eventId = sckFromBrowser || ('rf_purchase_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9));

// Montar user_data — apenas campos com hash válido
const userData = {};
const emHash = sha256(email);                  if (emHash) userData.em = [emHash];
const fnHash = sha256(firstName);              if (fnHash) userData.fn = [fnHash];
const lnHash = sha256(lastName);               if (lnHash) userData.ln = [lnHash];
const phHash = sha256(normalizePhone(phone));  if (phHash) userData.ph = [phHash];
const zpHash = sha256(zip);                    if (zpHash) userData.zp = [zpHash];
userData.country = [country];

return [{
  json: {
    eventId,
    eventTime: Math.floor(Date.now() / 1000),
    userData,
    customData: {
      currency:     'USD',
      value:        parseFloat(orderValue),
      content_name: 'Raices de Fe',
      content_type: 'product',
      order_id:     orderId,
    },
    debug: { email, firstName, lastName, country, orderId }
  }
}];

